/**
 * Serves Digital Asset Links for the Play TWA.
 * Fingerprints come from native/production-url.json via `npm run twa:sync`.
 * Source file: public/.well-known/assetlinks.json (regenerated by npm run twa:sync).
 */
import assetlinks from "../../public/.well-known/assetlinks.json";

interface AssetLinksEvent {
  url: URL;
  req: { method: string };
}

export default function assetlinksMiddleware(event: AssetLinksEvent, next: () => unknown): unknown {
  const method = (event.req.method ?? "GET").toUpperCase();
  if (method !== "GET" && method !== "HEAD") return next();
  if (event.url.pathname !== "/.well-known/assetlinks.json") return next();
  const body = method === "HEAD" ? null : JSON.stringify(assetlinks);
  return new Response(body, {
    status: 200,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-cache",
    },
  });
}
